  @protected
  void sse_encode_media_action(MediaAction self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case MediaAction_Play():
        sse_encode_i_32(0, serializer);
      case MediaAction_Pause():
        sse_encode_i_32(1, serializer);
      case MediaAction_Toggle():
        sse_encode_i_32(2, serializer);
      case MediaAction_Next():
        sse_encode_i_32(3, serializer);
      case MediaAction_Previous():
        sse_encode_i_32(4, serializer);
      case MediaAction_Stop():
        sse_encode_i_32(5, serializer);
      case MediaAction_SeekTo(positionMs: final positionMs):
        sse_encode_i_32(6, serializer);
        sse_encode_i_64(positionMs, serializer);
      case MediaAction_SeekBy(deltaMs: final deltaMs):
        sse_encode_i_32(7, serializer);
        sse_encode_i_64(deltaMs, serializer);
      case MediaAction_SetVolume(volume: final volume):
        sse_encode_i_32(8, serializer);
        sse_encode_f_64(volume, serializer);
      case MediaAction_Raise():
        sse_encode_i_32(9, serializer);
      case MediaAction_Quit():
        sse_encode_i_32(10, serializer);
    }
  }

