  @protected
  void sse_encode_player_event(PlayerEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case PlayerEvent_TrackStarted(id: final id):
        sse_encode_i_32(0, serializer);
        sse_encode_String(id, serializer);
      case PlayerEvent_TrackEnded(id: final id, error: final error):
        sse_encode_i_32(1, serializer);
        sse_encode_String(id, serializer);
        sse_encode_opt_String(error, serializer);
      case PlayerEvent_Position(
        id: final id,
        positionMs: final positionMs,
        durationMs: final durationMs,
        buffered: final buffered,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_String(id, serializer);
        sse_encode_i_64(positionMs, serializer);
        sse_encode_opt_box_autoadd_i_64(durationMs, serializer);
        sse_encode_opt_box_autoadd_f_32(buffered, serializer);
      case PlayerEvent_State(
        playing: final playing,
        buffering: final buffering,
        hasTrack: final hasTrack,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_bool(playing, serializer);
        sse_encode_bool(buffering, serializer);
        sse_encode_bool(hasTrack, serializer);
      case PlayerEvent_MediaControl(action: final action):
        sse_encode_i_32(4, serializer);
        sse_encode_box_autoadd_media_action(action, serializer);
      case PlayerEvent_DeviceChanged(
        name: final name,
        sampleRate: final sampleRate,
      ):
        sse_encode_i_32(5, serializer);
        sse_encode_String(name, serializer);
        sse_encode_u_32(sampleRate, serializer);
      case PlayerEvent_Error(message: final message):
        sse_encode_i_32(6, serializer);
        sse_encode_String(message, serializer);
      case PlayerEvent_Analysis(
        id: final id,
        bpm: final bpm,
        key: final key,
        camelot: final camelot,
        reliable: final reliable,
        detail: final detail,
      ):
        sse_encode_i_32(7, serializer);
        sse_encode_String(id, serializer);
        sse_encode_opt_box_autoadd_f_64(bpm, serializer);
        sse_encode_opt_String(key, serializer);
        sse_encode_opt_String(camelot, serializer);
        sse_encode_bool(reliable, serializer);
        sse_encode_String(detail, serializer);
      case PlayerEvent_MixPlanned(
        fromId: final fromId,
        toId: final toId,
        summary: final summary,
        beatmatched: final beatmatched,
        startsInMs: final startsInMs,
      ):
        sse_encode_i_32(8, serializer);
        sse_encode_String(fromId, serializer);
        sse_encode_String(toId, serializer);
        sse_encode_String(summary, serializer);
        sse_encode_bool(beatmatched, serializer);
        sse_encode_i_64(startsInMs, serializer);
      case PlayerEvent_MixStarted(
        fromId: final fromId,
        toId: final toId,
        summary: final summary,
        style: final style,
        durationMs: final durationMs,
      ):
        sse_encode_i_32(9, serializer);
        sse_encode_String(fromId, serializer);
        sse_encode_String(toId, serializer);
        sse_encode_String(summary, serializer);
        sse_encode_String(style, serializer);
        sse_encode_i_64(durationMs, serializer);
    }
  }

